import java.awt.*;import java.awt.event.*;import java.awt.image.*;import java.lang.reflect.*;import com.koios.client.Client;import com.koios.client.ui.*;import com.koios.client.arpg.ViewportScale;import com.koios.client.arpg.SkillPanel;import com.koios.client.arpg.ArpgTabs;
public class ViewportInputCheck {
 static class Surface extends Canvas {BufferedImage image;Surface(int w,int h){setSize(w,h);image=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);}public Graphics getGraphics(){return image.createGraphics();}}
 static class App extends RSApplet {Surface surface;App(int w,int h){surface=new Surface(w,h);myWidth=getRealScreenWidth();myHeight=getRealScreenHeight();}public Component getGameComponent(){return surface;}void mark(){updateGraphics(false);graphics.setColor(Color.RED);graphics.fillRect(100,100,10,10);}}
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{Client.frameMode=ScreenMode.RESIZABLE;Field clickX=RSApplet.class.getDeclaredField("clickX"),clickY=RSApplet.class.getDeclaredField("clickY");clickX.setAccessible(true);clickY.setAccessible(true);for(int[] size:new int[][]{{1280,720},{1920,1080},{2533,1407},{3840,2160}}){App app=new App(size[0],size[1]);double scale=app.displayScale();check(app.getRealScreenWidth()>=1024,"Logical canvas too narrow");int top=SkillPanel.barTop(app.getRealScreenWidth(),app.getRealScreenHeight()),ox=SkillPanel.barOffset(app.getRealScreenWidth());for(int slot=0;slot<3;slot++)check(SkillPanel.barSlotAt(ox+22+slot*127,top+42,app.getRealScreenWidth(),app.getRealScreenHeight())==slot,"Visible skill slot click shifted");check(top+60<=app.getRealScreenHeight()-165||ox+12>=519,"Skill bar overlaps chat");app.mark();int physical=(int)Math.ceil(105*scale);check(app.surface.image.getRGB(physical,physical)==Color.RED.getRGB(),"Render scale differs from viewport");for(int[] point:new int[][]{{100,100},{700,400},{app.getRealScreenWidth()-40,app.getRealScreenHeight()-50}}){int x=(int)Math.ceil(point[0]*scale)+app.offsetX,y=(int)Math.ceil(point[1]*scale)+app.offsetY;MouseEvent event=new MouseEvent(app.surface,MouseEvent.MOUSE_MOVED,0,0,x,y,1,false,MouseEvent.BUTTON1);app.mouseMoved(event);check(app.mouseX==point[0]&&app.mouseY==point[1],"Hover target shifted");app.mousePressed(event);check(clickX.getInt(app)==point[0]&&clickY.getInt(app)==point[1],"Click target shifted");app.mouseDragged(event);check(app.mouseX==point[0]&&app.mouseY==point[1],"Drag target shifted");}}check("tree".equals(ArpgTabs.action(2,20,210,0,0)),"Passive tab destination");check("skills".equals(ArpgTabs.action(5,20,210,0,0)),"Support tab destination");check("skills".equals(ArpgTabs.action(6,20,210,0,0)),"Skills tab destination");check(ArpgTabs.action(6,20,10,0,0)==null,"Tab background should not activate a button");check(ViewportScale.factor(3840,2160,true)==1,"Fixed mode must retain native size");System.out.println("Actual render, hover, click and drag scaling passed at four viewport sizes.");System.exit(0);}
}
